samples.sql:
SELECT MAX("Percent (%) Eligible Free (K-12)") AS HighestEligibleFreeRate
FROM frpm
WHERE "County" = 'Alameda';

SELECT COUNT(CDSCode) / 12 AS MonthlyAverageSchools
FROM schools
WHERE DOC = 52 AND County = 'Alameda' AND strftime('%Y', OpenDate) = '1980';

SELECT CAST(SUM(CASE WHEN T1.status = 'A' THEN T1.amount ELSE 0 END) AS REAL) * 100 / SUM(T1.amount) AS percentage
FROM loan AS T1
INNER JOIN account AS T2 ON T1.account_id = T2.account_id;

SELECT COUNT(trans_id) AS withdrawal_count
FROM trans
WHERE type = 'VYBER KARTOU' AND strftime('%Y', date) > '1995';

SELECT COUNT(*) AS non_carcinogenic_molecules
FROM molecule
WHERE label = '-';

SELECT CAST(COUNT(CASE WHEN T1.bond_type = '#' THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T2.molecule_id) AS percentage_of_triple_bonds
FROM bond AS T1
JOIN molecule AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT EXISTS (
    SELECT 1
    FROM molecule
    WHERE label = 'TR151'
) AND EXISTS (
    SELECT 1
    FROM molecule
    WHERE label = '+'
);

SELECT CAST(SUM(CASE WHEN T1.label = '+' AND T2.element = 'cl' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.molecule_id) AS percentage
FROM molecule AS T1
JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT ROUND(COUNT(CASE WHEN T1.bond_type = '-' THEN 1 ELSE NULL END) * 100 / COUNT(T1.bond_id), 2) AS percentage
FROM bond AS T1
JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT COUNT(*) AS infinite_power_count
FROM cards
WHERE power = '*';

SELECT EXISTS (
    SELECT 1
    FROM cards
    WHERE name = 'Angel of Mercy'
) AND EXISTS (
    SELECT 1
    FROM sets
    WHERE code = (
        SELECT setCode
        FROM cards
        WHERE name = 'Angel of Mercy'
    ) AND mtgoCode IS NOT NULL
);

SELECT COUNT(Id) AS NumberOfUsers
FROM users
WHERE LastAccessDate > '2014-09-01';

SELECT SUM(FavoriteCount) AS TotalFavoriteCount
FROM posts
WHERE OwnerUserId = 686 AND CAST(CreationDate AS DATE) LIKE '2011%';

SELECT COUNT(*) AS PositiveCommentCount
FROM comments
WHERE Score > 60;

SELECT COUNT(*) AS VoteCount
FROM votes
WHERE YEAR(CreationDate) = 2010;

SELECT COUNT(*) AS AdultUserCount
FROM users
WHERE Age BETWEEN 19 AND 65;

SELECT DisplayName
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT CAST(COUNT(CASE WHEN T2.TagName = 'r' THEN T1.Id ELSE NULL END) AS REAL) * 100 / COUNT(CASE WHEN T1.OwnerDisplayName = 'Community' THEN T1.Id ELSE NULL END) AS percentage
FROM posts AS T1
INNER JOIN tags AS T2 ON T1.Id = T2.PostId;

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(*) AS NegativeCommentCount
FROM comments
WHERE UserId = 13 AND Score < 60;

SELECT COUNT(Id) AS NumberOfPostsAboveAverage
FROM posts
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT COUNT(Id) AS NumberOfPosts
FROM posts
WHERE ViewCount > 35000 AND CommentCount = 0;

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT SUM(CASE WHEN T1.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN T1.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) AS difference
FROM publisher AS T1
JOIN superhero AS T2 ON T1.id = T2.publisher_id;

SELECT COUNT(*) AS number_of_neutral_superheroes
FROM superhero
WHERE alignment_id = 3;

SELECT COUNT(T1.superhero_name) FROM superhero AS T1
JOIN hero_attribute AS T2 ON T1.id = T2.hero_id
WHERE T2.attribute_name = 'Speed' AND T2.attribute_value = 100;

SELECT location, country, lat, lng
FROM circuits
WHERE name = 'Hungaroring';

SELECT AVG(T1.year) AS average_races_per_year
FROM races AS T1
WHERE T1.date BETWEEN '2000-01-01' AND '2010-12-31';

SELECT SUM(height) / COUNT(id) AS average_height
FROM Player
WHERE birthday >= '1990-01-01 00:00:00' AND birthday < '1996-01-01 00:00:00';

SELECT COUNT(*) AS player_count
FROM Player
WHERE strftime('%Y', birthday) > '1990';

SELECT player_name
FROM Player
WHERE strftime('%Y', 'now') - strftime('%Y', birthday) >= 35;

SELECT CAST(COUNT(CASE WHEN T1.height < 180 AND T1.overall_rating > 70 THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T1.id) AS percentage
FROM Player_Attributes AS T1
JOIN Player AS T2 ON T1.player_api_id = T2.player_api_id;

SELECT CAST(COUNT(CASE WHEN T1.SEX = 'F' AND (T2.TP < 6.0 OR T2.TP > 8.5) THEN T1.ID ELSE NULL END) AS REAL) * 100 / COUNT(T1.ID) AS Percentage
FROM Patient AS T1
JOIN Laboratory AS T2 ON T1.ID = T2.ID;

SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';

SELECT CAST(SUM(CASE WHEN T2.remaining < 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.event_id) AS percentage_over_budget
FROM event AS T1
JOIN budget AS T2 ON T1.event_id = T2.link_to_event;
